"use strict";
/**
 * Bundler regression — reachability, disk reconciliation, and honest status.
 *
 * `bundle_skill.py` discovers what to copy by walking a skill's own files and
 * following references to a fixed point. The loop itself has been correct since
 * the bundler's first commit. What was wrong is *reachability into it*: a file
 * already sitting in `<skill>/references/` that the walk no longer reaches was
 * never opened, never compared, never refreshed — and the bundler then printed
 * `in sync`.
 *
 * Measured on this repo before the fix: 858 bundled files, 749 regenerated by a
 * clean run, 109 never regenerated. Of those, 26 had a `shared/resources/`
 * source and 8 were provably stale — including two copies of a pipeline contract
 * carrying `"current_step": 1`, the exact value the shared source's own warning
 * block exists to forbid. Zero of the 749 discovered files were stale, so the
 * bundler was correct on everything it examined and silent about everything else.
 *
 * Two causes, and one tempting fix that had to be rejected:
 *   1. `.json` was absent from REFS_REF_RE's suffix alternation, so a skill whose
 *      only reference was `references/x.json` computed |needed| == 0, took the
 *      early return, and never touched its references/ dir at all.
 *   2. Most of them are reachable by no rule at all — something placed the copy and
 *      nothing points at it any more. Pass 2 therefore reconciles against DISK: a
 *      copy is refreshed because it exists and has a source, not because discovery
 *      found it.
 *
 * REJECTED: following `references/X` out of shared text. It looks like the obvious
 * fix and it over-vendors — `tracker-card-summary.md` names `references/jira-sync.js`
 * while explicitly avoiding the `shared/resources/` form so the bundler will NOT
 * vendor a Jira client into GitHub-only skills. Trying it added 38 unwanted files.
 * A prose mention is not a dependency; the guard test below pins that.
 *
 * The boundary that matters: a `references/` file WITH a `shared/resources/`
 * source is a stale copy and gets refreshed; one WITHOUT a source is a
 * skill-native file and must be left alone. 83 of the 109 are the latter.
 *
 * Each test builds a throwaway repo and runs the real bundler, so the assertions
 * are about observed behaviour rather than a re-implementation of its regexes.
 *
 * Run: node --test tests/bundle-transitive.test.js
 */

const fs = require("fs");
const os = require("os");
const path = require("path");
const { execFileSync } = require("child_process");
const test = require("node:test");
const assert = require("node:assert/strict");

const REPO_ROOT = path.resolve(__dirname, "..");
const BUNDLER = path.join(
  REPO_ROOT,
  "skills",
  "create-skill",
  "scripts",
  "bundle_skill.py",
);

const SKILL_MD_HEAD = `---
name: fixture-skill
description: Fixture skill used by the bundler reachability regression test.
---

# Fixture Skill
`;

/** The provenance banner the bundler injects — what marks a file as its output. */
const BANNER = (name) =>
  `<!-- AUTO-GENERATED — DO NOT EDIT. Source: shared/resources/${name}. ` +
  `Regenerate via \`npm run bundle\`. -->\n`;

/**
 * Build a disposable repo with one skill plus a shared/resources tree.
 *
 * Unlike the helper in bundle-mjs.test.js this does NOT run the bundler eagerly —
 * these tests need to bundle, mutate a source, and bundle again, which is the
 * only way to observe a refresh (as opposed to an initial copy).
 *
 * A real temp repo keeps the test from mutating tracked files: the bundler
 * rewrites sources in place by design.
 */
function makeFixture({ skillFiles = {}, sharedFiles = {}, refsFiles = {} }, t) {
  // `t` is required, and cleanup is registered IMMEDIATELY after mkdtemp — before
  // any file is written. Registering it at the end leaked the temp repo whenever
  // fixture construction threw, and an optional `t` let a future test leak
  // silently instead of failing.
  if (!t || typeof t.after !== "function") {
    throw new Error(
      "makeFixture requires the test context `t` for temp-dir cleanup",
    );
  }
  const root = fs.mkdtempSync(path.join(os.tmpdir(), "bundle-transitive-"));
  t.after(() => fs.rmSync(root, { recursive: true, force: true }));
  // find_repo_root() walks up looking for these markers.
  fs.mkdirSync(path.join(root, "skills"), { recursive: true });
  fs.mkdirSync(path.join(root, "shared", "resources"), { recursive: true });
  fs.writeFileSync(path.join(root, "package.json"), '{"name":"fixture"}\n');

  const skillDir = path.join(root, "skills", "fixture-skill");
  fs.mkdirSync(skillDir, { recursive: true });

  const writeAll = (base, files) => {
    for (const [rel, content] of Object.entries(files)) {
      const dest = path.join(base, rel);
      fs.mkdirSync(path.dirname(dest), { recursive: true });
      fs.writeFileSync(dest, content);
    }
  };

  writeAll(skillDir, skillFiles);
  writeAll(path.join(root, "shared", "resources"), sharedFiles);
  // Pre-existing bundled copies — the state a real checkout is in.
  writeAll(path.join(skillDir, "references"), refsFiles);

  const bundle = () =>
    execFileSync("python3", [BUNDLER, skillDir], { encoding: "utf-8" });

  // Run the bundler with arbitrary argv. Returns {status, stdout} rather than
  // throwing — a non-zero exit is the expected result in several tests below.
  const run = (argv) => {
    try {
      return {
        status: 0,
        stdout: execFileSync("python3", [BUNDLER, ...argv], {
          encoding: "utf-8",
        }),
      };
    } catch (e) {
      // A signal kill gives status null; a missing python3 gives ENOENT with
      // status undefined. Neither is a bundler verdict — surface it as itself
      // rather than letting it masquerade as a staleness assertion failure.
      if (e.status == null) throw e;
      return { status: e.status, stdout: (e.stdout || "") + (e.stderr || "") };
    }
  };

  return {
    root,
    skillDir,
    bundle,
    run,
    // `--check` AFTER the target — the argument order that used to be ignored.
    // (`--all` cannot be used in a fixture: it resolves the skills dir from the
    // bundler's own __file__, which points at the real repository.)
    checkArgsReversed: () => run([skillDir, "--check"]),
    readShared: (name) =>
      fs.readFileSync(path.join(root, "shared", "resources", name), "utf-8"),
    chmodShared: (name, mode) =>
      fs.chmodSync(path.join(root, "shared", "resources", name), mode),
    chmodRef: (name, mode) =>
      fs.chmodSync(path.join(skillDir, "references", name), mode),
    symlinkRef: (name, target) => {
      const dest = path.join(skillDir, "references", name);
      fs.mkdirSync(path.dirname(dest), { recursive: true });
      fs.symlinkSync(target, dest);
    },
    writeShared: (name, content) =>
      fs.writeFileSync(path.join(root, "shared", "resources", name), content),
    readRef: (name) =>
      fs.readFileSync(path.join(skillDir, "references", name), "utf-8"),
    refExists: (name) => fs.existsSync(path.join(skillDir, "references", name)),
    check: () => run(["--check", skillDir]),
  };
}

test("a copy reachable by no discovery rule is REFRESHED when its source changes", (t) => {
  // The real shape of the defect. All 26 affected files in this repo were already
  // sitting in references/ — put there by an earlier bundle or a hand-sync — and
  // nothing the walk can see points at them any more. Discovery cannot be widened
  // to reach them (see the over-vendoring guard below), so reconciliation keys on
  // the copy existing and having a source.
  const fx = makeFixture(
    {
      skillFiles: {
        "SKILL.md": `${SKILL_MD_HEAD}\nNo shared references here.\n`,
      },
      sharedFiles: { "contract.md": "# Contract\n\nORIGINAL body.\n" },
      refsFiles: { "contract.md": "# Contract\n\nORIGINAL body.\n" },
    },
    t,
  );

  fx.bundle();
  fx.writeShared("contract.md", "# Contract\n\nCORRECTED body.\n");
  const stdout = fx.bundle();

  assert.match(
    fx.readRef("contract.md"),
    /CORRECTED body/,
    "This is the defect in full: the source moved on and the bundled copy did not, " +
      "so the copy describes an earlier version forever while the bundler reports " +
      `success. Bundler said:\n${stdout}`,
  );
});

test("`in sync` is not printed when a source-backed copy was actually refreshed", (t) => {
  const fx = makeFixture(
    {
      skillFiles: {
        "SKILL.md": `${SKILL_MD_HEAD}\nNo shared references here.\n`,
      },
      sharedFiles: { "contract.md": "# Contract\n\nCURRENT body.\n" },
      // A real bundled copy carries the provenance banner — that is what marks it
      // as bundler output rather than hand-authored content.
      refsFiles: {
        "contract.md": `${BANNER("contract.md")}# Contract\n\nSTALE body.\n`,
      },
    },
    t,
  );

  const stdout = fx.bundle();

  assert.doesNotMatch(
    stdout,
    /in sync/,
    `A run that rewrote a stale file must not report it as already correct. Said:\n${stdout}`,
  );
  assert.match(
    stdout,
    /reconciled/,
    `The refresh should be reported so the operator can see it happened. Said:\n${stdout}`,
  );
});

test("a `references/X` mention inside shared PROSE does not vendor the file", (t) => {
  // Regression guard for an over-correction found while implementing this task.
  // Following `references/X` out of shared text looks like the obvious fix for
  // unreachable copies, and it is wrong: `shared/resources/tracker-card-summary.md`
  // names `references/jira-sync.js` while stating outright that it avoids the
  // `shared/resources/` form so the bundler will NOT vendor a Jira client into
  // GitHub-only skills. Making prose a dependency edge added 38 unwanted files
  // across this repo. Only files a skill actually reaches, or already holds, belong
  // in its references/.
  const fx = makeFixture(
    {
      skillFiles: {
        "SKILL.md": `${SKILL_MD_HEAD}\nSee shared/resources/spec.md.\n`,
      },
      sharedFiles: {
        "spec.md":
          "# Spec\n\nHelpers live in the shared library (vendored as " +
          "`references/heavy-client.js` in skills that need it). Its path is " +
          "deliberately not spelled out.\n",
        "heavy-client.js": "module.exports = {};\n",
      },
    },
    t,
  );

  fx.bundle();

  assert.equal(
    fx.refExists("heavy-client.js"),
    false,
    "A prose mention is not a dependency. Vendoring on the strength of one puts a " +
      "Jira client into every GitHub-only skill that merely documents the contract.",
  );
});

test("`references/x.json` is discovered — .json must be in the suffix alternation", (t) => {
  const fx = makeFixture(
    {
      skillFiles: {
        "SKILL.md": `${SKILL_MD_HEAD}\nThe graph lives in \`references/graph.json\`.\n`,
      },
      sharedFiles: {
        "graph.json": '{\n  "fixture-skill": []\n}\n',
      },
    },
    t,
  );

  const stdout = fx.bundle();

  assert.ok(
    fx.refExists("graph.json"),
    "A skill whose only reference is `references/graph.json` must still bundle " +
      "it. Without `json` in the suffix alternation the skill computes " +
      "|needed| == 0, takes the early return, and never touches references/ at " +
      `all. Bundler said:\n${stdout}`,
  );
});

test("a stale copy WITH a shared source is reconciled even when discovery cannot reach it", (t) => {
  const fx = makeFixture(
    {
      skillFiles: {
        // SKILL.md references nothing at all — orphan.md is unreachable by any rule.
        "SKILL.md": `${SKILL_MD_HEAD}\nNo shared references here.\n`,
      },
      sharedFiles: {
        "orphan.md": "# Orphan\n\nCURRENT source body.\n",
      },
      refsFiles: {
        "orphan.md": `${BANNER("orphan.md")}# Orphan\n\nANCIENT stale body.\n`,
      },
    },
    t,
  );

  const stdout = fx.bundle();

  assert.match(
    fx.readRef("orphan.md"),
    /CURRENT source body/,
    "A file sitting in references/ that has a shared/resources/ counterpart is a " +
      "stale copy, whatever discovery thinks. Pass 2 must reconcile against disk, " +
      `not only against the discovered set. Bundler said:\n${stdout}`,
  );
});

test("a copy WITHOUT a shared source is left untouched — the out-of-scope boundary", (t) => {
  const NATIVE =
    "# Skill-native\n\nThis file has no shared/resources source.\n";
  const fx = makeFixture(
    {
      skillFiles: { "SKILL.md": `${SKILL_MD_HEAD}\nNothing shared.\n` },
      sharedFiles: {},
      refsFiles: { "skill-native.md": NATIVE },
    },
    t,
  );

  fx.bundle();

  assert.equal(
    fx.readRef("skill-native.md"),
    NATIVE,
    "83 of this repo's 109 non-regenerated bundled files are skill-native and " +
      "legitimately live in references/. Reconciliation must key on HAVING a " +
      "source, never on mere presence, or it deletes or clobbers them.",
  );
});

test("the bundler stays idempotent — a second run reports no changes", (t) => {
  const fx = makeFixture(
    {
      skillFiles: {
        "SKILL.md": `${SKILL_MD_HEAD}\nSee shared/resources/outer.md.\n`,
      },
      sharedFiles: {
        "outer.md": "# Outer\n\nRun `references/inner.md`.\n",
        "inner.md": "# Inner\n\nBody.\n",
      },
    },
    t,
  );

  fx.bundle();
  const second = fx.bundle();

  assert.match(
    second,
    /in sync/,
    "Idempotence is a load-bearing contract (AGENTS.md, the module docstring, and " +
      "the validate.yml freshness step all depend on it). A second run must be a " +
      `no-op. Bundler said:\n${second}`,
  );
});

test("--check fails on a staled copy that discovery cannot reach", (t) => {
  const fx = makeFixture(
    {
      skillFiles: { "SKILL.md": `${SKILL_MD_HEAD}\nNothing shared.\n` },
      sharedFiles: { "orphan.md": "# Orphan\n\nCURRENT source body.\n" },
      refsFiles: {
        "orphan.md": `${BANNER("orphan.md")}# Orphan\n\nANCIENT stale body.\n`,
      },
    },
    t,
  );

  const res = fx.check();

  assert.equal(
    res.status,
    1,
    "This is the case the existing regenerate-and-git-diff CI check is " +
      "structurally blind to: the bundler never writes the file, so git sees no " +
      "diff and the lane stays green while the copy is stale. --check must " +
      `compare per-file instead. Output:\n${res.stdout}`,
  );
  assert.match(
    res.stdout,
    /orphan\.md/,
    "The failure must name the offending file so the operator can act on it.",
  );
});

test("--check passes on a correctly bundled tree, and writes nothing", (t) => {
  const fx = makeFixture(
    {
      skillFiles: {
        "SKILL.md": `${SKILL_MD_HEAD}\nSee shared/resources/outer.md.\n`,
      },
      sharedFiles: { "outer.md": "# Outer\n\nBody.\n" },
    },
    t,
  );

  fx.bundle();
  const before = fx.readRef("outer.md");
  const res = fx.check();

  assert.equal(
    res.status,
    0,
    `--check should pass here. Output:\n${res.stdout}`,
  );
  assert.equal(
    fx.readRef("outer.md"),
    before,
    "--check must be read-only — CI runs it to detect drift, not to repair it.",
  );
});

// ---------------------------------------------------------------------------
// QA cycle 1 findings (TASK86-001 … 005). Each fix gets a test; a fix without
// one is not held. Every test below was confirmed red against the code as it
// stood when the finding was raised.
// ---------------------------------------------------------------------------

test("TASK86-001: --check is honoured after the target, and does not write", (t) => {
  const fx = makeFixture(
    {
      skillFiles: {
        "SKILL.md": `${SKILL_MD_HEAD}\nNo shared references here.\n`,
      },
      sharedFiles: { "contract.md": "# Contract\n\nCURRENT body.\n" },
      refsFiles: {
        "contract.md": `${BANNER("contract.md")}# Contract\n\nSTALE body.\n`,
      },
    },
    t,
  );

  // Argument order reversed (`<path> --check`). This used to set check_mode=false,
  // fall through to the mutating path, and rewrite the repo while exiting 0 — a
  // read-only flag performing writes because it was not in position 0. The same
  // parse bug made `--all --check` bundle every skill in the repository.
  const before = fx.readRef("contract.md");
  const res = fx.checkArgsReversed();

  assert.equal(
    res.status,
    1,
    `<path> --check must still be a CHECK and must fail on stale input. Output:\n${res.stdout}`,
  );
  assert.equal(
    fx.readRef("contract.md"),
    before,
    "…and it must not have written anything. A read-only flag that rewrites the " +
      "repository when the arguments are the other way round is the worst shape " +
      "this bug can take: silent, order-dependent, and exit 0.",
  );
});

test("TASK86-001: an unknown --flag is rejected instead of falling through to a write", (t) => {
  const fx = makeFixture(
    {
      skillFiles: {
        "SKILL.md": `${SKILL_MD_HEAD}\nSee shared/resources/a.md.\n`,
      },
      sharedFiles: { "a.md": "# A\n\nBody.\n" },
    },
    t,
  );

  const res = fx.run(["--chekc", fx.skillDir]); // typo for --check
  assert.equal(
    res.status,
    2,
    `A misspelt flag must be refused, not silently ignored — ignoring it runs a ` +
      `mutating bundle when the caller asked for a check. Output:\n${res.stdout}`,
  );
  assert.equal(
    fx.refExists("a.md"),
    false,
    "…and nothing may be written on the rejected path.",
  );
});

test("TASK86-002: --check catches a lost .sh executable bit", (t) => {
  const fx = makeFixture(
    {
      skillFiles: {
        "SKILL.md": `${SKILL_MD_HEAD}\nSee shared/resources/tool.sh.\n`,
      },
      sharedFiles: { "tool.sh": "#!/usr/bin/env bash\necho hi\n" },
    },
    t,
  );
  fx.chmodShared("tool.sh", 0o755);
  fx.bundle();

  // Bytes still match; only the mode drifted. bundle_skill() treats mode as part
  // of being in sync, so a check that ignores it disagrees with the bundler —
  // and the `git diff` form this replaced DID catch it, because git tracks the bit.
  fx.chmodRef("tool.sh", 0o644);
  const res = fx.check();

  assert.equal(
    res.status,
    1,
    `A bundled .sh whose executable bit was lost must fail the check. Otherwise CI ` +
      `is green while 'npm run bundle' would repair it locally — the green-CI-but-` +
      `stale split this whole task exists to close. Output:\n${res.stdout}`,
  );
  assert.match(
    res.stdout,
    /WRONG MODE/,
    "the failure must name the mode problem",
  );
});

test("TASK86-003: an orphaned copy whose source was deleted is reported", (t) => {
  const fx = makeFixture(
    {
      skillFiles: {
        "SKILL.md": `${SKILL_MD_HEAD}\nNo shared references here.\n`,
      },
      sharedFiles: {},
      refsFiles: {
        "gone.md": `${BANNER("gone.md")}# Gone\n\nSource deleted.\n`,
      },
    },
    t,
  );

  const res = fx.check();
  assert.equal(
    res.status,
    1,
    `A copy carrying a banner that names a source which no longer exists must be ` +
      `reported. It is in neither discovery nor reconciliation — both need the ` +
      `source — so it would stay green forever. Output:\n${res.stdout}`,
  );
  assert.match(
    res.stdout,
    /ORPHANED/,
    "the failure must say the source is gone",
  );
});

test("TASK86-004: a same-named hand-authored file is reported, never overwritten", (t) => {
  const AUTHORED = "# Hand-authored\n\nThis is NOT bundler output.\n";
  const fx = makeFixture(
    {
      skillFiles: {
        "SKILL.md": `${SKILL_MD_HEAD}\nNo shared references here.\n`,
      },
      sharedFiles: { "read-config.sh": "#!/usr/bin/env bash\n: shared\n" },
      refsFiles: { "read-config.sh": AUTHORED },
    },
    t,
  );

  fx.bundle();

  assert.equal(
    fx.readRef("read-config.sh"),
    AUTHORED,
    "Sharing a filename with a shared resource is not evidence of being a stale " +
      "copy of it. Overwriting an authored file and stamping it AUTO-GENERATED " +
      "destroys work the bundler never created.",
  );

  const res = fx.check();
  assert.equal(res.status, 1, "…but it must not be silent about it either.");
  assert.match(
    res.stdout,
    /AMBIGUOUS/,
    "the collision must be surfaced for a human",
  );
});

test("TASK86-004: a pre-header-injection copy IS still reconciled", (t) => {
  // The banner alone is too strict a discriminator, and this is why: copies
  // bundled before header injection existed carry no banner. Three of the eight
  // files this task corrected were exactly that shape, so a banner-only gate
  // would have refused to fix the very files it was written for.
  const fx = makeFixture(
    {
      skillFiles: {
        "SKILL.md": `${SKILL_MD_HEAD}\nNo shared references here.\n`,
      },
      sharedFiles: { "legacy.md": "# Legacy\n\nOriginal body.\n" },
      refsFiles: { "legacy.md": "# Legacy\n\nOriginal body.\n" }, // no banner
    },
    t,
  );

  fx.bundle(); // identical-to-source ⇒ recognised as bundler output ⇒ gets the banner
  fx.writeShared("legacy.md", "# Legacy\n\nUPDATED body.\n");
  const stdout = fx.bundle();

  assert.match(
    fx.readRef("legacy.md"),
    /UPDATED body/,
    `A banner-less copy that is byte-identical to the rewritten source is ` +
      `demonstrably bundler output and must keep being refreshed. Bundler said:\n${stdout}`,
  );
});

test("TASK86-005: a symlinked reference on the DISCOVERY path is not written through", (t) => {
  // The original version of this test had SKILL.md reference nothing, so the
  // bundler took the early return and wrote nothing at all — "the source is
  // unchanged" was trivially true and the test passed with either guard removed.
  // Naming the file puts it in `needed`, which forces the write path.
  const fx = makeFixture(
    {
      skillFiles: {
        "SKILL.md": `${SKILL_MD_HEAD}\nSee shared/resources/linked.md.\n`,
      },
      sharedFiles: { "linked.md": "# Linked\n\nSource body.\n" },
    },
    t,
  );
  const sourceBefore = fx.readShared("linked.md");
  fx.symlinkRef("linked.md", "../../../shared/resources/linked.md");

  fx.bundle();

  assert.equal(
    fx.readShared("linked.md"),
    sourceBefore,
    "write_bytes writes THROUGH a symlink, so a reference linked back at its own " +
      "source would get the AUTO-GENERATED banner injected into shared/resources/ " +
      "itself — permanently, after which --check reports STALE forever.",
  );
});

test("TASK86-005: a symlinked reference is reported, not silently accepted", (t) => {
  const fx = makeFixture(
    {
      skillFiles: {
        "SKILL.md": `${SKILL_MD_HEAD}\nSee shared/resources/linked.md.\n`,
      },
      sharedFiles: { "linked.md": "# Linked\n\nSource body.\n" },
    },
    t,
  );
  fx.symlinkRef("linked.md", "../../../shared/resources/linked.md");

  const res = fx.check();
  assert.equal(
    res.status,
    1,
    `Making symlinks safe also made them invisible: neither reported nor repaired, ` +
      `while a consumer copying the directory verbatim gets a dangling link. ` +
      `Output:\n${res.stdout}`,
  );
  assert.match(
    res.stdout,
    /SYMLINK/,
    "the link must be named as its own problem class",
  );
});

// ---------------------------------------------------------------------------
// QA cycle 2 findings (TASK86-006/007). One root cause: the marker PHRASE was
// treated as provenance, so a document that merely quotes the banner was taken
// for one. Fixed by matching the banner's structure — `Source:
// shared/resources/<the file's own path>` — validated against the tree at 774
// matches, 0 mismatches.
// ---------------------------------------------------------------------------

test("TASK86-007: a file that merely QUOTES the banner is not overwritten", (t) => {
  const AUTHORED =
    "# Authored guide\n\nBundled files carry AUTO-GENERATED — DO NOT EDIT at the top.\n";
  const fx = makeFixture(
    {
      skillFiles: {
        "SKILL.md": `${SKILL_MD_HEAD}\nNo shared references here.\n`,
      },
      sharedFiles: { "guide.md": "# Shared guide\n\nShared content.\n" },
      refsFiles: { "guide.md": AUTHORED },
    },
    t,
  );

  fx.bundle();

  assert.equal(
    fx.readRef("guide.md"),
    AUTHORED,
    "Quoting the banner is not carrying one. Treating the phrase as provenance " +
      "overwrote this file wholesale — the exact destruction the ambiguity check " +
      "exists to prevent, in its likeliest case: a document ABOUT the bundler is " +
      "precisely what quotes its banner.",
  );

  const res = fx.check();
  assert.equal(res.status, 1, "…and the collision must still be surfaced.");
  assert.match(
    res.stdout,
    /AMBIGUOUS/,
    "reported as ambiguous, not silently kept",
  );
});

test("TASK86-006: a source-less file quoting the banner is not called ORPHANED", (t) => {
  const fx = makeFixture(
    {
      skillFiles: {
        "SKILL.md": `${SKILL_MD_HEAD}\nNo shared references here.\n`,
      },
      sharedFiles: {},
      refsFiles: {
        // No same-named source, and no real banner — just prose mentioning it.
        "notes.md":
          "# Notes\n\nWe stamp copies with AUTO-GENERATED — DO NOT EDIT.\n",
      },
    },
    t,
  );

  const res = fx.check();
  assert.equal(
    res.status,
    0,
    `A skill-native document that mentions the banner has no provenance to be ` +
      `orphaned FROM. Reporting it turns a green lane red over prose. Output:\n${res.stdout}`,
  );
});

test("TASK86-006: a genuine orphan is still reported, and names its own declared source", (t) => {
  const fx = makeFixture(
    {
      skillFiles: {
        "SKILL.md": `${SKILL_MD_HEAD}\nNo shared references here.\n`,
      },
      sharedFiles: {},
      refsFiles: { "gone.md": `${BANNER("gone.md")}# Gone\n` },
    },
    t,
  );

  const res = fx.check();
  assert.equal(
    res.status,
    1,
    "a real banner whose source vanished is still an orphan",
  );
  assert.match(
    res.stdout,
    /ORPHANED \(banner names shared\/resources\/gone\.md/,
    "the reported path must come from the banner the file carries, not be inferred " +
      "from its location — otherwise the message asserts something it never read",
  );
});

// ---------------------------------------------------------------------------
// QA cycle 2, refute-pass findings. The headline one: the ambiguity gate had
// exactly one call site — reconciliation — so the guarantee held precisely
// where the danger was smallest, and the test asserting it used the one fixture
// seed that routed to the branch that worked.
// ---------------------------------------------------------------------------

for (const [label, skillBody] of [
  ["names it as references/X", "Use `references/guard.md`.\n"],
  ["names it as shared/resources/X", "See shared/resources/guard.md.\n"],
  ["names nothing (reconciliation path)", "Nothing.\n"],
]) {
  test(`TASK86-008: an authored file survives when SKILL.md ${label}`, (t) => {
    const AUTHORED = "# Authored\n\nHand-written, not bundler output.\n";
    const fx = makeFixture(
      {
        skillFiles: { "SKILL.md": `${SKILL_MD_HEAD}\n${skillBody}` },
        sharedFiles: { "guard.md": "# Shared\n\nShared body.\n" },
        refsFiles: { "guard.md": AUTHORED },
      },
      t,
    );

    fx.bundle();

    assert.equal(
      fx.readRef("guard.md"),
      AUTHORED,
      `The gate must hold on EVERY path into a write, not just the one a ` +
        `convenient fixture exercises. Discovery reaching the name is the ` +
        `ORDINARY case; reconciliation is the rare one.`,
    );

    const res = fx.check();
    assert.equal(res.status, 1, "…and it must be reported, not silently kept.");
    assert.match(res.stdout, /AMBIGUOUS/);
  });
}

test("TASK86-009: a single-dash typo is refused and writes nothing", (t) => {
  const fx = makeFixture(
    {
      skillFiles: {
        "SKILL.md": `${SKILL_MD_HEAD}\nSee shared/resources/a.md.\n`,
      },
      sharedFiles: { "a.md": "# A\n" },
    },
    t,
  );

  const res = fx.run(["-check", fx.skillDir]);
  assert.equal(
    res.status,
    2,
    `'-check' was treated as a skill path, so a single-dash typo on a READ-ONLY ` +
      `request ran the mutating bundle and exited 0. Output:\n${res.stdout}`,
  );
  assert.equal(fx.refExists("a.md"), false, "…and nothing may be written.");
});

test("TASK86-010: a 0755 non-.sh source keeps its bit, and drift is caught", (t) => {
  const fx = makeFixture(
    {
      skillFiles: {
        "SKILL.md": `${SKILL_MD_HEAD}\nSee shared/resources/tool.js.\n`,
      },
      sharedFiles: { "tool.js": "#!/usr/bin/env node\nconsole.log(1);\n" },
    },
    t,
  );
  fx.chmodShared("tool.js", 0o755);
  fx.bundle();

  fx.chmodRef("tool.js", 0o644);
  const res = fx.check();

  assert.equal(
    res.status,
    1,
    `Keying the mode rule on the '.sh' suffix left a real 0755 '.js' source with ` +
      `0644 copies in this very repo — invisible to check AND unrepairable by ` +
      `bundle. Output:\n${res.stdout}`,
  );
  assert.match(res.stdout, /WRONG MODE/);

  fx.bundle(); // the bundler must also be able to REPAIR it
  assert.equal(
    fx.check().status,
    0,
    "npm run bundle must clear a mode-only drift",
  );
});

test("TASK86-011: a header-less suffix is not auto-accepted as bundler output", (t) => {
  const AUTHORED = "export const x = 1;\n";
  const fx = makeFixture(
    {
      skillFiles: { "SKILL.md": `${SKILL_MD_HEAD}\nNothing.\n` },
      sharedFiles: { "thing.ts": "export const y = 2;\n" },
      refsFiles: { "thing.ts": AUTHORED },
    },
    t,
  );

  fx.bundle();

  assert.equal(
    fx.readRef("thing.ts"),
    AUTHORED,
    `Accepting every suffix autogen_header declines meant '.mdx', '.ts' and '.txt' ` +
      `were auto-accepted on a bare name match. This tree already holds 15 ` +
      `skill-native .mdx files and one .ts.`,
  );

  const res = fx.check();
  assert.equal(
    res.status,
    1,
    "…and the collision must be reported, as its siblings do",
  );
  assert.match(res.stdout, /AMBIGUOUS/);
});

test("TASK86-012: a banner naming a different path is reported MISDECLARED", (t) => {
  const fx = makeFixture(
    {
      skillFiles: { "SKILL.md": `${SKILL_MD_HEAD}\nNothing.\n` },
      sharedFiles: {},
      refsFiles: { "renamed.md": `${BANNER("original.md")}# Renamed\n` },
    },
    t,
  );

  const res = fx.check();
  assert.equal(
    res.status,
    1,
    "a moved/renamed copy must not vanish from the report",
  );
  assert.match(
    res.stdout,
    /MISDECLARED/,
    "requiring declared == own path fixes the prose false positive but silently " +
      "drops the renamed case unless it gets a class of its own",
  );
});

test("TASK86-013: the remedy matches the problem class", (t) => {
  const fx = makeFixture(
    {
      skillFiles: { "SKILL.md": `${SKILL_MD_HEAD}\nNothing.\n` },
      sharedFiles: {},
      refsFiles: { "gone.md": `${BANNER("gone.md")}# Gone\n` },
    },
    t,
  );

  const res = fx.check();
  assert.equal(res.status, 1);
  assert.match(
    res.stdout,
    /NOT clear them/,
    "`npm run bundle` cannot clear ORPHANED — printing it as the remedy leaves CI " +
      "permanently red with an instruction that provably does nothing",
  );
});

test("TASK86-014: a symlink no rule discovers is still reported", (t) => {
  // Found while verifying the cycle-2 fixes: `source_backed_on_disk` skipped
  // symlinks, so one that discovery does not reach entered neither the expected
  // set nor the orphan scan and nothing said anything about it. The same
  // membership-vs-writability conflation fixed for AMBIGUOUS, left in one place.
  const fx = makeFixture(
    {
      skillFiles: { "SKILL.md": `${SKILL_MD_HEAD}\nNothing.\n` },
      sharedFiles: { "link.md": "# Link\n\nSource body.\n" },
    },
    t,
  );
  const before = fx.readShared("link.md");
  fx.symlinkRef("link.md", "../../../shared/resources/link.md");

  fx.bundle();
  const res = fx.check();

  assert.equal(
    res.status,
    1,
    `A symlinked reference is our concern whether or not discovery reaches it — ` +
      `a consumer copying the directory verbatim gets a dangling link. ` +
      `Output:\n${res.stdout}`,
  );
  assert.match(res.stdout, /SYMLINK/);
  assert.equal(
    fx.readShared("link.md"),
    before,
    "and the source stays untouched",
  );
});

// ---------------------------------------------------------------------------
// QA cycle 3. Two of these close TEST gaps rather than code defects: a
// behaviour that no assertion pinned is a behaviour the next change can delete
// silently.
// ---------------------------------------------------------------------------

test("F-001: --check asserts pass 3, not only references/", (t) => {
  const fx = makeFixture(
    {
      skillFiles: {
        "SKILL.md": `${SKILL_MD_HEAD}\nSee shared/resources/g.md.\n`,
      },
      sharedFiles: { "g.md": "# G\n" },
    },
    t,
  );
  fx.bundle(); // rewrites SKILL.md, bundles g.md

  // A skill source that still names shared/resources/ — references/ is fresh.
  fs.writeFileSync(
    path.join(fx.skillDir, "guide.md"),
    "# Guide\n\nSee shared/resources/g.md.\n",
  );

  const res = fx.check();
  assert.equal(
    res.status,
    1,
    `The check looked only inside references/, so a skill source awaiting a pass-3 ` +
      `rewrite passed while 'npm run bundle' would change it — the same ` +
      `green-CI-but-dirty-tree split, in the dimension the check had dropped. ` +
      `Output:\n${res.stdout}`,
  );
  assert.match(res.stdout, /UNREWRITTEN/);
});

test("F-002: mode drift is caught in BOTH directions", (t) => {
  const fx = makeFixture(
    {
      skillFiles: {
        "SKILL.md": `${SKILL_MD_HEAD}\nSee shared/resources/t.sh.\n`,
      },
      sharedFiles: { "t.sh": "#!/usr/bin/env bash\necho hi\n" }, // 0644 source
    },
    t,
  );
  fx.bundle();
  fx.chmodRef("t.sh", 0o755); // copy GAINS a bit the source never had

  const res = fx.check();
  assert.equal(
    res.status,
    1,
    `Gating on "is the source executable" caught a copy that LOST its +x but not ` +
      `one that gained one — and git ships the bit to consumers. Output:\n${res.stdout}`,
  );
  assert.match(res.stdout, /WRONG MODE/);

  fx.bundle();
  assert.equal(fx.check().status, 0, "and the bundler must repair it");
});

test("F-003: an authored .json is not destroyed, and is not called regenerable", (t) => {
  const AUTHORED = '{\n  "authored": true\n}\n';
  const fx = makeFixture(
    {
      skillFiles: { "SKILL.md": `${SKILL_MD_HEAD}\nNothing.\n` },
      sharedFiles: { "cfg.json": '{\n  "shared": true\n}\n' },
      refsFiles: { "cfg.json": AUTHORED },
    },
    t,
  );

  fx.bundle();

  assert.equal(
    fx.readRef("cfg.json"),
    AUTHORED,
    `A '.json' early return skipped the evidence check entirely, so an authored ` +
      `.json was silently overwritten — and --check then called it STALE and told ` +
      `the operator to run the bundler that would destroy it.`,
  );
  const res = fx.check();
  assert.match(
    res.stdout,
    /AMBIGUOUS/,
    "it must be reported as needing a decision",
  );
});

test("F-004: a DANGLING symlink (no source) is still reported", (t) => {
  const fx = makeFixture(
    {
      skillFiles: { "SKILL.md": `${SKILL_MD_HEAD}\nNothing.\n` },
      sharedFiles: {},
    },
    t,
  );
  fx.symlinkRef("nope.md", "../../../shared/resources/nope.md");

  const res = fx.check();
  assert.equal(
    res.status,
    1,
    `This is the MORE dangerous half — the link is already dangling for anyone ` +
      `copying the directory verbatim — and it reached neither the expected set ` +
      `nor source_backed_on_disk. Output:\n${res.stdout}`,
  );
  assert.match(res.stdout, /SYMLINK/);
});

test("F-005: a mode-only repair is REPORTED, not silently counted as in sync", (t) => {
  const fx = makeFixture(
    {
      skillFiles: {
        "SKILL.md": `${SKILL_MD_HEAD}\nSee shared/resources/t.sh.\n`,
      },
      sharedFiles: { "t.sh": "#!/usr/bin/env bash\necho hi\n" },
    },
    t,
  );
  fx.chmodShared("t.sh", 0o755);
  fx.bundle();
  fx.chmodRef("t.sh", 0o644);

  const stdout = fx.bundle();
  assert.doesNotMatch(
    stdout,
    /in sync/,
    `The bundler mutated the tree (it chmod'd the file) — saying 'in sync' is the ` +
      `same class of untruth this whole task is about. Said:\n${stdout}`,
  );
});

test("F-006: the banner window survives long YAML frontmatter", (t) => {
  // Every other fixture has 1–3 line frontmatter, so the line-based window was
  // load-bearing but unexercised: the suite would stay green with the old
  // 512-byte window restored, which misclassified a real file in this repo.
  const longDescription = "x".repeat(700);
  const fx = makeFixture(
    {
      skillFiles: { "SKILL.md": `${SKILL_MD_HEAD}\nNothing.\n` },
      sharedFiles: {
        "long.md": `---\nname: long\ndescription: ${longDescription}\n---\n\n# Long\n`,
      },
      refsFiles: {},
    },
    t,
  );
  // Bundle it in by naming it, then confirm the round-trip is clean.
  fs.writeFileSync(
    path.join(fx.skillDir, "SKILL.md"),
    `${SKILL_MD_HEAD}\nSee shared/resources/long.md.\n`,
  );
  fx.bundle();

  assert.equal(
    fx.check().status,
    0,
    "the banner lands after ~740 bytes of frontmatter; a byte-bounded window cuts " +
      "the marker in half and misclassifies a correctly-bundled copy",
  );
});

// ---------------------------------------------------------------------------
// QA cycle 4. Three of these pin behaviours the cycle-4 review proved were held
// by NOTHING — each was mutation-verified as unpinned before being written.
// ---------------------------------------------------------------------------

test("C4-001: UNREWRITTEN converges — it is not raised for work the bundler will not do", (t) => {
  // Pass 3 runs after bundle_skill's early return, so a skill whose only
  // shared/resources mention names a MISSING file rewrites nothing. Reporting
  // UNREWRITTEN there left CI permanently red behind "Run npm run bundle" — a
  // remedy that provably does nothing, which is the exact failure TASK86-013
  // exists to prevent, reintroduced by the fix for F-001.
  const fx = makeFixture(
    {
      skillFiles: {
        "SKILL.md": `${SKILL_MD_HEAD}\nSee shared/resources/missing.md.\n`,
      },
      sharedFiles: {},
    },
    t,
  );

  fx.bundle();
  assert.equal(
    fx.check().status,
    0,
    "a check that cannot be cleared by its own printed remedy is worse than no check",
  );
  fx.bundle();
  assert.equal(fx.check().status, 0, "and it must stay converged");
});

test("C4-002: pass 3 does not corrupt URLs or fenced blocks, but still rewrites prose", (t) => {
  const fx = makeFixture(
    {
      skillFiles: {
        "SKILL.md": [
          SKILL_MD_HEAD,
          "",
          "Docs: https://github.com/acme/x/blob/main/shared/resources/real.md",
          "",
          "```bash",
          "cp mylib.sh shared/resources/real.md",
          "```",
          "",
          "An ordinary reference `shared/resources/real.md` must still be rewritten.",
          "",
        ].join("\n"),
      },
      sharedFiles: { "real.md": "# Real\n" },
    },
    t,
  );

  fx.bundle();
  const after = fs.readFileSync(path.join(fx.skillDir, "SKILL.md"), "utf-8");

  assert.match(
    after,
    /blob\/main\/shared\/resources\/real\.md/,
    "rewriting a URL turns a working link into a 404",
  );
  assert.match(
    after,
    /cp mylib\.sh shared\/resources\/real\.md/,
    "rewriting inside a fenced block turns an instruction into a wrong one",
  );
  assert.match(
    after,
    /`references\/real\.md` must still be rewritten/,
    "but an inline span is the ordinary way to name a shared resource — exempting " +
      "it would defeat the bundler",
  );
});

test("C4-003: pass 2 still rewrites inside fenced blocks (the opposite rule)", (t) => {
  // rewrite_text and rewrite_source_text are NOT interchangeable. A bundled copy
  // must have its fenced `source ../references/x.sh` snippets rewritten or the
  // installed skill cannot run. Applying pass 3's exemption to pass 2 rewrote 77
  // real files on the first attempt at this fix.
  const fx = makeFixture(
    {
      skillFiles: {
        "SKILL.md": `${SKILL_MD_HEAD}\nSee shared/resources/doc.md.\n`,
      },
      sharedFiles: {
        "doc.md": "# Doc\n\n```bash\ncat shared/resources/other.md\n```\n",
        "other.md": "# Other\n",
      },
    },
    t,
  );

  fx.bundle();
  assert.match(
    fx.readRef("doc.md"),
    /cat references\/other\.md/,
    "a bundled copy's fenced snippet must be rewritten to resolve in an install",
  );
});

test("C4-004: MISDECLARED beats AMBIGUOUS when the file has a live same-named source", (t) => {
  // The expected-set MISDECLARED branch was pinned by nothing: TASK86-012's
  // fixture has no same-named source, so it exercises the ORPHAN-scan branch,
  // a different one. Mutating `if misdeclared:` to `if False:` left 35 green.
  const fx = makeFixture(
    {
      skillFiles: { "SKILL.md": `${SKILL_MD_HEAD}\nNothing.\n` },
      sharedFiles: { "x.md": "# X\n" },
      refsFiles: { "x.md": `${BANNER("y.md")}# X copy\n` },
    },
    t,
  );

  const res = fx.check();
  assert.equal(res.status, 1);
  assert.match(
    res.stdout,
    /MISDECLARED/,
    "the file HAS a banner — it names the wrong path",
  );
  // Scoped to the file's own line: the summary block LISTS the class names
  // ("the AMBIGUOUS / ORPHANED / MISDECLARED / SYMLINK lines"), so a bare
  // doesNotMatch over stdout fails on the explainer rather than on the verdict.
  const line = res.stdout
    .split("\n")
    .find((l) => l.includes("references/x.md is"));
  assert.match(line, /MISDECLARED/);
  assert.doesNotMatch(
    line,
    /AMBIGUOUS/,
    "'add the banner' is unactionable advice for a file that already has one",
  );
});

test("C4-005: a non-skill path is a usage error (exit 2), not drift", (t) => {
  // UsageError, its raise and its catch were pinned by nothing: replacing the
  // raise with `return []` left 35 green, so cycle 3's F-009 could have been
  // reverted in silence.
  const fx = makeFixture(
    {
      skillFiles: { "SKILL.md": `${SKILL_MD_HEAD}\nNothing.\n` },
      sharedFiles: {},
    },
    t,
  );
  const res = fx.run(["--check", path.join(fx.root, "no-such-skill")]);
  assert.equal(
    res.status,
    2,
    `A bad path reported as exit 1 reads to CI as bundle drift. Output:\n${res.stdout}`,
  );
});

test("C4-006: UNREWRITTEN is bucketed as regenerable", (t) => {
  // The bucket was named in the cycle-3 commit message and pinned by nothing.
  // The fixture must bundle FIRST: otherwise references/ is empty, MISSING lands
  // in the regenerable bucket too, and the assertion passes for the wrong reason.
  // (That is exactly how the first version of this test was vacuous — MUT-29
  // removed UNREWRITTEN from the bucket and nothing went red.)
  const fx = makeFixture(
    {
      skillFiles: {
        "SKILL.md": `${SKILL_MD_HEAD}\nSee \`shared/resources/r.md\`.\n`,
      },
      sharedFiles: { "r.md": "# R\n" },
    },
    t,
  );
  fx.bundle(); // references/ now complete and rewritten — no MISSING, no STALE
  assert.equal(
    fx.check().status,
    0,
    "precondition: the only later problem is pass 3",
  );

  // Re-introduce an un-rewritten skill source. UNREWRITTEN is now the ONLY problem.
  fs.writeFileSync(
    path.join(fx.skillDir, "guide.md"),
    "# Guide\n\nSee `shared/resources/r.md`.\n",
  );

  const res = fx.check();
  assert.equal(res.status, 1);
  assert.match(res.stdout, /UNREWRITTEN/);
  assert.match(
    res.stdout,
    /Run 'npm run bundle'/,
    "UNREWRITTEN IS fixable by the bundler, so it belongs in the regenerable bucket",
  );
});

test("C4-007: an out-of-tree reference is refused, not written outside references/", (t) => {
  // `name` is an unsanitised regex capture permitting `.` and `/`, so
  // `shared/resources/../../OUTSIDE.md` escaped both refs_dir and the skill:
  // the bundler printed "bundled references/../../OUTSIDE.md" and created
  // <root>/skills/OUTSIDE.md. Overwriting an existing file was already blocked
  // by the write gate; CREATING one was not.
  const fx = makeFixture(
    {
      skillFiles: {
        "SKILL.md": `${SKILL_MD_HEAD}\nSee shared/resources/../../OUTSIDE.md.\n`,
      },
      sharedFiles: {},
    },
    t,
  );
  // Place the file where the traversal actually resolves.
  fs.writeFileSync(path.join(fx.root, "OUTSIDE.md"), "# outside\n");

  const stdout = fx.bundle();

  assert.equal(
    fs.existsSync(path.join(fx.root, "skills", "OUTSIDE.md")),
    false,
    `The bundler must never create a file outside the skill's references/. Said:\n${stdout}`,
  );
  assert.match(stdout, /refusing out-of-tree reference/);
});
